mapper.select:
SELECT auction.*, winner.username AS winner_username
FROM auction LEFT JOIN user winner ON winner.id = auction.winner_id
WHERE auction.id = #{id}

SELECT auction.*, winner.username AS winner_username
FROM auction LEFT JOIN user winner ON winner.id = auction.winner_id
WHERE auction.ticket_id = #{ticketId}

mapper.update:
UPDATE auction
SET current_bid = #{currentBid}, winner_id = #{winnerId}
WHERE id = #{id}

UPDATE auction
SET status = 'ended', winner_id = #{winnerId}
WHERE id = #{id}
